/* Source: shared/lib/ui.js; syncFollowUpDates. Generated by standalone-build.mjs. */
function syncFollowUpDates(){
    document.querySelectorAll('[data-followup-date][data-followup-offset]').forEach(node => {
      const when=followUpAppointmentFor(node);
      if(!when){if(window.kraneTreatmentPause?.hasCancelledFollowup(node.dataset.followupCase))node.textContent=window.kraneTreatmentPause.isPaused(node.dataset.followupCase)?'พักโปรแกรม':'ไม่มีนัดติดตาม';return;}
      const pad=value => String(value).padStart(2,'0');
      node.setAttribute('data-followup-iso',`${when.getFullYear()}-${pad(when.getMonth()+1)}-${pad(when.getDate())}`);
      node.setAttribute('data-followup-at',when.toISOString());
      const text=node.hasAttribute('data-followup-time')
        ? `${formatFollowUpDate(when)} · ${formatFollowUpTime(when)}`
        : formatFollowUpDate(when);
      if(node.textContent!==text) node.textContent=text;
    });
  }

/* Source: shared/lib/clinical.js; followUpAppointmentFor. Generated by standalone-build.mjs. */
function followUpAppointmentFor(node){
    if(!node) return null;
    const program=window.kraneTreatmentPause;
    if(program?.isPaused(node.dataset.followupCase))return null;
    const resumed=program?.appointmentFor(node.dataset.followupCase);
    if(resumed)return new Date(resumed);
    if(program?.hasCancelledFollowup(node.dataset.followupCase))return null;
    const caseId=node.dataset.followupCase || node.dataset.followupIso || String(node.dataset.followupOffset || 'followup');
    if(followUpAppointments.has(caseId)) return followUpAppointments.get(caseId);
    const offset=Number(node.dataset.followupOffset);
    if(!Number.isFinite(offset)) return null;
    let when;
    const seededMinutes=Number(node.dataset.followupDemoMinutes);
    if(Number.isFinite(seededMinutes)){
      /* The profile's normal demo data must still read like a real clinic
         appointment. Keep it at the next 11:00 business-day slot instead of
         deriving a late-night time from when the page happens to be opened.
         The explicit demo states remain relative so QA can exercise the room
         opening transition without waiting. */
      if(followUpDemoState==='ready' || followUpDemoState==='now'){
        const demoMinutes=followUpDemoState==='ready' ? 8 : 0;
        when=new Date(Date.now()+(demoMinutes*60000));
        when.setMilliseconds(0);
      }else{
        when=new Date();
        when.setHours(11,0,0,0);
        if(when.getTime()<=Date.now()) when.setDate(when.getDate()+1);
        while(when.getDay()===0 || when.getDay()===6) when.setDate(when.getDate()+1);
      }
    }else{
      when=new Date();
      when.setHours(10,0,0,0);
      when.setDate(when.getDate()+offset);
    }
    followUpAppointments.set(caseId,when);
    return when;
  }

/* Source: shared/lib/ui.js; formatFollowUpDate. Generated by standalone-build.mjs. */
function formatFollowUpDate(when){
    if(!when || Number.isNaN(when.getTime())) return '';
    const thai=document.documentElement.lang==='th';
    const months=thai ? FOLLOWUP_MONTHS_TH : FOLLOWUP_MONTHS_EN;
    return `${when.getDate()} ${months[when.getMonth()]} ${when.getFullYear()}`;
  }

/* Source: shared/lib/ui.js; formatFollowUpTime. Generated by standalone-build.mjs. */
function formatFollowUpTime(when){
    if(!when || Number.isNaN(when.getTime())) return '';
    const pad=value => String(value).padStart(2,'0');
    const time=`${pad(when.getHours())}:${pad(when.getMinutes())}`;
    return document.documentElement.lang==='th' ? `${time} น.` : time;
  }
